  // hurwitzZetaComplex's doc comment for why EM alone cancels here.
  let m = floor(a - 0.5);
  let h = a - m - 1.0;
  if (abs(h) > 0.75) { return _gpu_hurwitz_zeta_em(s, a, s - 1.0); }
